package com.com.aftermotionske.tools;

import java.util.HashMap;
import java.util.Map;

// Generated at build time from the wrapped site's HTML/CSS/JS. Each
// file's bytes are stored base64-encoded as a compiled string constant
// (part of classes.dex), not as a loose file under assets/.
// MainActivity's shouldInterceptRequest override (see EMBED_HOST) decodes
// these on demand to feed the WebView, in place of the OS resolving
// file:///android_asset/ requests against a real assets/ folder.
public final class EmbeddedAssets {
    // Joins base64 chunks at class-init time. Deliberately NOT string
    // concatenation on the call site (see the comment above each F<n>
    // field) -- a method call is not a compile-time constant expression,
    // so javac can't fold these chunks back into one oversized constant.
    private static String join(String... parts) {
        StringBuilder sb = new StringBuilder();
        for (String p : parts) sb.append(p);
        return sb.toString();
    }

    private static final String F0 = join(
            "");

    private static final String F1 = join(
            "");

    private static final String F2 = join(
            "");

    private static final String F3 = join(
            "ewogICJuYW1lIjogImFtLW5lbyIsCiAgInZlcnNpb24iOiAiMS4wLjAiLAogICJtYWluIjogInNlcnZlci5qcyIsCiAgInNjcmlwdHMiOiB7CiAgICAic3RhcnQiOiAibm9kZSBzZXJ2ZXIuanMiCiAgfSwKICAiZGVwZW5kZW5jaWVzIjogewogICAgImF4aW9zIjogIl4xLjcuOSIsCiAgICAiY29ycyI6ICJeMi44LjUiLAogICAgImV4cHJlc3MiOiAiXjQuMjEuMiIKICB9Cn0=");

    private static final String F4 = join(
            "");

    private static final String F5 = join(
            "ewogICJ0b3RhbFByZW1pdW0iOiAxNTU3LAogICJ0b2RheVByZW1pdW0iOiAxNCwKICAibGFzdERhdGUiOiAiMjAyNi0wOS0wOCIKfQ==");

    private static final String F6 = join(
            "");

    private static final String F7 = join(
            "");

    private static final String F8 = join(
            "");

    private static final String F9 = join(
            "");

    private static final String F10 = join(
            "");

    private static final String F11 = join(
            "");

    private static final String F12 = join(
            "");

    private static final String F13 = join(
            "");

    private static final String F14 = join(
            "");

    private static final String F15 = join(
            "");

    private static final Map<String, String> MAP = new HashMap<>();
    static {
        MAP.put("am-reverse/LICENSE", F0);
        MAP.put("am-reverse/README.md", F1);
        MAP.put("am-reverse/am.js", F2);
        MAP.put("am-reverse/package.json", F3);
        MAP.put("am-reverse/server.js", F4);
        MAP.put("am-reverse/data/stats.json", F5);
        MAP.put("am-reverse/lib/auth.js", F6);
        MAP.put("am-reverse/lib/errors.js", F7);
        MAP.put("am-reverse/lib/stats.js", F8);
        MAP.put("am-reverse/public/index.html", F9);
        MAP.put("am-reverse/app/api/index.js", F10);
        MAP.put("am-reverse/app/api/route.js", F11);
        MAP.put("am-reverse/app/api/send-link/route.js", F12);
        MAP.put("am-reverse/app/api/stats/route.js", F13);
        MAP.put("am-reverse/app/api/status/route.js", F14);
        MAP.put("am-reverse/app/api/verify-link/route.js", F15);
    }

    // rel: path as it would have appeared under assets/, e.g. "index.html"
    // or "css/style.css". Returns null if nothing was embedded at that path.
    public static byte[] get(String rel) {
        String b64 = MAP.get(rel);
        if (b64 == null) return null;
        byte[] raw = android.util.Base64.decode(b64, android.util.Base64.DEFAULT);
        return raw;
    }

    private EmbeddedAssets() {}
}
